import itertools
import math

def is_perfect_square(k):
    if k < 0:
        return False
    root = int(math.isqrt(k))
    return root * root == k

def is_cool(n):
    """Checks if n is a cool integer."""
    numbers = list(range(1, n + 1))

    # Iterate through all permutations and check the prefix sums
    for p in itertools.permutations(numbers):
        current_sum = 0
        is_valid = True
        for i in range(n):
            current_sum += p[i]
            if is_perfect_square(current_sum):
                is_valid = False
                break
        if is_valid:
            return True  # Found a valid permutation
    return False

cool_integers = []
for n in range(1, 21):
    if is_cool(n):
        cool_integers.append(n)

print("Cool integers up to 20:", cool_integers)

